sys_script_include.script:
var CheckAvailability = Class.create();
CheckAvailability.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkAvailabilityOfBook: function() {
        var bookId = this.getParameter('sysparm_book_sys_id'); 
		console.log('---check availability---', bookId);
        var bookGR = new GlideRecord('sn_lms_books'); 
		 bookGR.addQuery("sys_id", bookId);
        bookGR.query();
        if (bookGR.next()) {
			console.log('---in bookrecord gr---');
            if (bookGR.available_copies.toString() > 0) {
                return JSON.stringify({
                    is_available: true,
                    nearest_return_date: null,
                });
            } else {
				console.log('---in else--');
                var requestRecord = new GlideRecord('sn_lms_book_requests');
                requestRecord.addQuery('book_id', bookId);
                requestRecord.addQuery('status', '!=', 'completed'); 
                requestRecord.orderBy('return_date');
                requestRecord.query();
				console.log('---rpost query--');
                if (requestRecord.next()) {
                    var nearestReturnDate = requestRecord.getValue('return_date');
                    return JSON.stringify({
                        is_available: false,
                        nearest_return_date: nearestReturnDate.toString(),
                    });
                }

            }
        }
	console.log('---return json--');
        // If no active requests are found or book not available
        return JSON.stringify({
            is_available: false
        });

    },

    type: 'CheckAvailability'
});
